rule.rule_attribute:
{#%- set rename = table.sourceTables[0].name -%#}
{%- set rename = table.name -%}
{%- if table.entityTypes.isEmpty -%}
    {%- set rename = "6empty#" + rename -%}
{%- else -%}
    {%- set rename = "7NOTempty#" + rename -%}
{%- endif -%}   
{%- for tableType in table.entityTypes -%}
    {%- from table.entityTypes as type where type.tablePrefix is defined and startsWithIgnoreCase(rename, type.tablePrefix) -%}
        {%- set rename = type.tablePrefix + rename -%}
    {%- endfrom -%}
    {%- from table.entityTypes as type where type.tableSuffix is defined and endsWithIgnoreCase(rename, type.tableSuffix) -%}
        {%- set rename = rename + type.tableSuffix -%}
    {%- endfrom -%}
    {%- from table.extendedProperties as ExtProp where ExtProp.name | upper == "SUBJECT_AREA" -%}
        {%- set rename = rename + "_" + ExtProp.value  -%}
    {%- endfrom -%}
{%- endfor -%}
{{- rename -}}

{#%- set rename = table.sourceTables[0].name -%#}
